/**
 * Transform Script Manager
 * Handles storage, loading, and management of custom transform scripts
 */

const CUSTOM_SCRIPTS_KEY = 'ts-transformer-custom-scripts';

/** Metadata (no code) for a stored custom transform script. */
interface CustomScriptMetadata {
	/** Unique identifier, generated by {@link generateScriptId}. */
	id: string;
	/** Human-readable display name. */
	name: string;
	/** Optional free-text description. */
	description: string;
	/** Unix timestamp (ms) when the script was first saved. */
	createdAt: number;
	/** Unix timestamp (ms) of the most recent update. */
	updatedAt: number;
	/** Optional search tags. */
	tags?: string[];
}

/** A custom transform script including its source {@link code}. */
export interface CustomScript extends CustomScriptMetadata {
	/** TypeScript source of the transformer function. */
	code: string;
}

/**
 * Upserts a custom transform script in `localStorage`.
 *
 * If a script with the given `id` already exists its `createdAt` timestamp is
 * preserved; otherwise a new entry is created.
 *
 * @param id - Unique identifier for the script.
 * @param name - Human-readable display name.
 * @param code - TypeScript source of the transformer function.
 * @param description - Optional free-text description.
 * @param tags - Optional search tags.
 * @returns The saved {@link CustomScript}.
 * @throws When `localStorage` is unavailable or the storage quota is exceeded.
 */
export function saveCustomScript(
	id: string,
	name: string,
	code: string,
	description: string = '',
	tags: string[] = []
): CustomScript {
	const scripts = getAllCustomScripts();
	const now = Date.now();

	const existingScript = scripts.find(s => s.id === id);

	const script: CustomScript = {
		id,
		name,
		code,
		description,
		tags,
		createdAt: existingScript?.createdAt ?? now,
		updatedAt: now
	};

	const scriptsCopy = scripts.filter(s => s.id !== id);
	scriptsCopy.push(script);

	try {
		localStorage.setItem(CUSTOM_SCRIPTS_KEY, JSON.stringify(scriptsCopy));
		return script;
	} catch (e) {
		console.error('Failed to save custom script:', e);
		throw new Error('Storage quota exceeded or localStorage unavailable');
	}
}

/**
 * Retrieves a single custom transform script from `localStorage` by its ID.
 *
 * @param id - The unique identifier of the script to load.
 * @returns The matching {@link CustomScript}, or `null` if not found.
 */
export function loadCustomScript(id: string): CustomScript | null {
	const scripts = getAllCustomScripts();
	return scripts.find(s => s.id === id) || null;
}

/**
 * Returns all custom transform scripts stored in `localStorage`, sorted by
 * insertion order. Returns an empty array on parse errors.
 *
 * @returns Array of {@link CustomScript} objects.
 */
export function getAllCustomScripts(): CustomScript[] {
	try {
		const stored = localStorage.getItem(CUSTOM_SCRIPTS_KEY);
		if (!stored) return [];
		return JSON.parse(stored) as CustomScript[];
	} catch (e) {
		console.error('Failed to load custom scripts:', e);
		return [];
	}
}

/**
 * Removes a custom transform script from `localStorage`.
 *
 * @param id - The unique identifier of the script to delete.
 * @returns `true` on success, `false` if the operation failed.
 */
export function deleteCustomScript(id: string): boolean {
	try {
		const scripts = getAllCustomScripts();
		const filtered = scripts.filter(s => s.id !== id);
		localStorage.setItem(CUSTOM_SCRIPTS_KEY, JSON.stringify(filtered));
		return true;
	} catch (e) {
		console.error('Failed to delete custom script:', e);
		return false;
	}
}

/**
 * Serialises a stored custom script to a pretty-printed JSON string.
 *
 * @param id - The unique identifier of the script to export.
 * @returns A JSON string representing the {@link CustomScript}, or `null` if
 *   no script with that ID exists.
 */
export function exportCustomScript(id: string): string | null {
	const script = loadCustomScript(id);
	if (!script) return null;

	return JSON.stringify(script, null, 2);
}

/**
 * Parses a JSON string and upserts the resulting script into `localStorage`.
 *
 * The JSON must contain at minimum `name` (string) and `code` (string).
 * If no `id` is provided a new one is generated via {@link generateScriptId}.
 *
 * @param json - JSON string representing a (partial) {@link CustomScript}.
 * @returns The saved {@link CustomScript}.
 * @throws `Error` if the JSON is malformed or missing required fields.
 */
export function importCustomScript(json: string): CustomScript {
	try {
		const parsed = JSON.parse(json) as Partial<CustomScript>;

		if (
			!parsed.name ||
			!parsed.code ||
			typeof parsed.name !== 'string' ||
			typeof parsed.code !== 'string'
		) {
			throw new Error('Invalid custom script format: missing required fields (name, code)');
		}

		const id = parsed.id || generateScriptId();
		const existing = loadCustomScript(id);

		return saveCustomScript(
			id,
			parsed.name,
			parsed.code,
			parsed.description || '',
			parsed.tags || []
		);
	} catch (e) {
		if (e instanceof SyntaxError) {
			throw new Error('Invalid JSON format');
		}
		throw e;
	}
}

/**
 * Generates a unique, collision-resistant script identifier combining the
 * current timestamp with a random base-36 suffix.
 *
 * @returns A string of the form `script-<timestamp>-<random>`.
 */
export function generateScriptId(): string {
	return `script-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Filters all stored custom scripts whose `name`, `description`, or `tags`
 * contain the given query string (case-insensitive).
 *
 * @param query - The search string to match against.
 * @returns Matching {@link CustomScript} objects.
 */
export function searchCustomScripts(query: string): CustomScript[] {
	const scripts = getAllCustomScripts();
	const lowerQuery = query.toLowerCase();

	return scripts.filter(
		s =>
			s.name.toLowerCase().includes(lowerQuery) ||
			s.description.toLowerCase().includes(lowerQuery) ||
			(s.tags?.some(tag => tag.toLowerCase().includes(lowerQuery)) ?? false)
	);
}

/**
 * Triggers a browser download of the given script as a `.json` file.
 *
 * Creates a temporary `<a>` element, clicks it, then removes it and revokes
 * the object URL to avoid memory leaks.
 *
 * @param script - The {@link CustomScript} to download.
 * @param filename - Optional override for the downloaded file name.
 *   Defaults to `<script.name>.json` (spaces replaced with `-`).
 */
export function downloadCustomScript(script: CustomScript, filename?: string): void {
	const json = JSON.stringify(script, null, 2);
	const blob = new Blob([json], { type: 'application/json' });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = filename || `${script.name.replace(/\s+/g, '-')}.json`;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
}

/**
 * Convenience helper that creates a new script entry from raw TypeScript code,
 * generates a fresh ID, and persists it to `localStorage`.
 *
 * @param name - Human-readable display name for the script.
 * @param code - TypeScript source of the transformer function.
 * @param description - Optional free-text description.
 * @returns The newly saved {@link CustomScript}.
 */
export function createScriptFromCode(
	name: string,
	code: string,
	description: string = ''
): CustomScript {
	const id = generateScriptId();
	return saveCustomScript(id, name, code, description, []);
}
